def calculate_a(N):
    # a_1 = 0
    if N == 1:
        return 0

    a = {1: 0}

    for n in range(2, N + 1):
        if n % 2 == 0:
            # Even case: a_{2k} = 2a_k + k. Here n = 2k, so k = n/2
            k = n // 2
            a[n] = 2 * a[k] + k
        else:
            # Odd case: a_{2k+1} = a_k + a_{k+1} + k. Here n = 2k+1, so k = (n-1)/2
            k = (n - 1) // 2
            a[n] = a[k] + a[k + 1] + k

    return a[N]

# Calculate a_15
a_15_calculated = calculate_a(15)
print(f"Calculated a_15: {a_15_calculated}")

def calculate_a_n(n):
    """Calculates a_n based on the derived recurrence relation."""
    memo = {1: 0}

    def get_a(k):
        if k in memo:
            return memo[k]

        if k % 2 == 0:
            m = k // 2
            # a_n = 2*a_m + m
            result = 2 * get_a(m) + m
        else:
            m = k // 2
            # a_n = a_m + a_{m+1} + m
            result = get_a(m) + get_a(m + 1) + m

        memo[k] = result
        return result

    return get_a(n)

target_n = 2025
